style.css:
@-moz-document domain("www.youtube.com") {
/* ---------- PROGRESS BAR (played portion) ---------- */
    .ytp-play-progress {
        background: linear-gradient(
            90deg,
            #363232 0%,
            #565656 25%,
            #6b6b6b 45%,
            #eea1e3 75%,
            #f4b5eb 100%
        ) !important;
    }

    /* ---------- BUFFER BAR ---------- */
    .ytp-load-progress {
        background: rgba(244, 181, 235, 0.25) !important;
    }

    /* ---------- HOVER PROGRESS (preview) ---------- */
    .ytp-hover-progress {
        background: rgba(238, 161, 227, 0.35) !important;
    }

    /* ---------- PROGRESS BAR BACKGROUND ---------- */
    .ytp-progress-list {
        background: rgba(54, 50, 50, 0.6) !important;
    }

    /* ---------- CHAPTER DIVIDERS ---------- */
    .ytp-chapter-hover-container .ytp-play-progress {
        background: linear-gradient(
            90deg,
            #363232 0%,
            #565656 25%,
            #6b6b6b 45%,
            #eea1e3 75%,
            #f4b5eb 100%
        ) !important;
    }

    /* ---------- SCRUBBER / PIN ---------- */

    /* Hide the default red circle */
    .ytp-scrubber-button {
        background: none !important;
        border: none !important;
        box-shadow: none !important;
    }

    .ytp-scrubber-container {
        overflow: visible !important;
        z-index: 9999 !important;
    }

    /* Kuromi pin image */
    .ytp-scrubber-container .ytp-scrubber-button {
        width: 28px !important;
        height: 28px !important;
        margin-top: -12px !important;
        margin-left: -14px !important;
        border-radius: 0 !important;
        background: url("https://i.imgur.com/P2jAuAs.png") center/contain no-repeat !important;
        transform: scale(1);
        transition:
            transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
            filter 0.3s ease;
        filter: drop-shadow(0 1px 3px rgba(0, 0, 0, 0.45));
        transform-origin: center bottom;
    }

    /* ---------- HOVER / DRAG MAGNIFY ANIMATION ---------- */

    /* When hovering the progress bar area → pin grows */
    .ytp-chrome-bottom:hover .ytp-scrubber-container .ytp-scrubber-button,
    .ytp-progress-bar-container:hover .ytp-scrubber-container .ytp-scrubber-button {
        transform: scale(1);
        filter: drop-shadow(0 2px 6px rgba(238, 161, 227, 0.5));
    }

    /* When actively dragging → pin gets even bigger with a glow */
    .ytp-scrubber-container.ytp-drag .ytp-scrubber-button,
    .ytp-progress-bar[aria-valuenow]:active .ytp-scrubber-container .ytp-scrubber-button,
    .ytp-scrubber-container:active .ytp-scrubber-button {
        transform: scale(1.35) !important;
        filter: drop-shadow(0 3px 10px rgba(244, 181, 235, 0.7)) !important;
        transition:
            transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1),
            filter 0.2s ease !important;
    }

    /* ---------- MINI-PLAYER PROGRESS BAR ---------- */
    .ytp-miniplayer-ui .ytp-play-progress {
        background: linear-gradient(
            90deg,
            #363232 0%,
            #6b6b6b 50%,
            #f4b5eb 100%
        ) !important;
    }

    /* ---------- SUBTLE SPARKLE KEYFRAME ---------- */
    @keyframes kuromi-pulse {
        0%, 100% {
            filter: drop-shadow(0 2px 6px rgba(238, 161, 227, 0.4));
        }
        50% {
            filter: drop-shadow(0 2px 10px rgba(244, 181, 235, 0.8));
        }
    }

    /* Apply pulse when hovered and idle on the bar */
    .ytp-progress-bar-container:hover .ytp-scrubber-container .ytp-scrubber-button {
        animation: kuromi-pulse 1.8s ease-in-out infinite;
    }

    /* Stop pulsing during active drag for snappy feel */
    .ytp-scrubber-container:active .ytp-scrubber-button {
        animation: none !important;
    }
}
